IF NOT EXISTS (SELECT * FROM sys.foreign_keys WHERE object_id = OBJECT_ID(N'[dbo].[FK_CompanyDomainSetting_Company]') AND parent_object_id = OBJECT_ID(N'[dbo].[CompanyDomainSetting]'))
begin
	ALTER TABLE [dbo].[CompanyDomainSetting]  WITH CHECK ADD  CONSTRAINT [FK_CompanyDomainSetting_Company] FOREIGN KEY([CompanyID]) REFERENCES [dbo].[Company] ([ID])
ON DELETE CASCADE;
	ALTER TABLE [dbo].[CompanyDomainSetting] CHECK CONSTRAINT [FK_CompanyDomainSetting_Company];
end

